export function ListsDemo() {
  const [items, setItems] = useState(['Morning yoga', 'Puja', 'Deep work']);
  const pool = ['Evening walk', 'Reading', 'Trikala Sandhya', 'Completion process'];
  const [next, setNext] = useState(0);
  const add = () => {
    const item = pool[next % pool.length];
    setNext(next + 1);
    setItems([...items, item]);
  };
  const removeLast = () => {
    setItems(items.slice(0, items.length - 1));
  };
  const clear = () => {
    setItems([]);
  };
  return (
    <>
      <RgList>
        {items.map((item, i) => (
          <RgRow key={item?.id ?? i} title={item} detail={('Item ' + (i + 1))} />
        ))}
      </RgList>
      {(items.length === 0) && (
        <RgText variant="bodyLarge">The list is empty. ngFor over an empty array renders nothing.</RgText>
      )}
      <RgText variant="bodyLarge">{items.length} items in the array, {items.length} rows on screen.</RgText>
      <RgButton onPress={() => add()}>Add an item</RgButton>
      <RgButton disabled={(items.length === 0)} onPress={() => removeLast()}>Remove the last</RgButton>
      <RgButton disabled={(items.length === 0)} onPress={() => clear()}>Clear the list</RgButton>
    </>
  );
}

