export function Stamp() {
  const log = __container.get<LifecycleLogService>(LifecycleLogService);
  useSyncExternalStore((cb) => log.__subscribe(cb), () => log.__getVersion());
  const ngOnInit = () => {
    log.entries = [...log.entries, 'Stamp created: ngOnInit ran'];
  };
  const ngOnDestroy = () => {
    log.entries = [...log.entries, 'Stamp removed: ngOnDestroy ran'];
  };
  useEffect(() => {
    ngOnInit();
    return () => {
      ngOnDestroy();
    };
  }, []);
  return (
    <RgText variant="bodyLarge">The stamp is on screen right now.</RgText>
  );
}

